/* Local-only CSV and XLSX reading. No file contents leave this browser. */
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const sep=text.split(/\r?\n/)[0].includes('\t')?'\t':text.split(/\r?\n/)[0].includes(';')?';':',';const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote;}else if(c===sep&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c;}if(quote)throw Error('Unclosed quote in CSV.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
async function readXlsx(buffer){const bytes=new Uint8Array(buffer),v=new DataView(buffer),decoder=new TextDecoder();let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('Not a valid .xlsx workbook. Export old .xls files as .xlsx or CSV.');let pos=v.getUint32(end+16,true),count=v.getUint16(end+10,true),files={},expanded=0;for(let n=0;n<count;n++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('Invalid workbook archive.');const method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),uncompressed=v.getUint32(pos+24,true),nl=v.getUint16(pos+28,true),el=v.getUint16(pos+30,true),cl=v.getUint16(pos+32,true),offset=v.getUint32(pos+42,true),name=decoder.decode(bytes.slice(pos+46,pos+46+nl));pos+=46+nl+el+cl;if(!name.startsWith('xl/')||!name.endsWith('.xml')&&!name.endsWith('.rels'))continue;expanded+=uncompressed;if(expanded>40e6)throw Error('Workbook expands beyond 40 MB. Export the schedule sheet as CSV.');const start=offset+30+v.getUint16(offset+26,true)+v.getUint16(offset+28,true);let data=bytes.slice(start,start+size);if(method===8)data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());else if(method!==0)throw Error('Unsupported workbook compression.');files[name]=decoder.decode(data);}
const xml=s=>new DOMParser().parseFromString(s||'<root/>','application/xml'),nodes=(d,k)=>[...d.getElementsByTagName(k)],text=n=>nodes(n,'t').map(t=>t.textContent).join(''),shared=nodes(xml(files['xl/sharedStrings.xml']),'si').map(text),book=xml(files['xl/workbook.xml']),rels=nodes(xml(files['xl/_rels/workbook.xml.rels']),'Relationship'),date1904=nodes(book,'workbookPr')[0]?.getAttribute('date1904')==='1';return nodes(book,'sheet').map(sh=>{let rel=rels.find(r=>r.getAttribute('Id')===sh.getAttribute('r:id'));let path=rel?.getAttribute('Target')||'';path=path.startsWith('/')?path.slice(1):'xl/'+path.replace(/^\.\//,'');const rows=nodes(xml(files[path]),'row').map(row=>{let out=[];for(const c of nodes(row,'c')){const letters=(c.getAttribute('r')||'A').match(/[A-Z]+/)[0];let col=0;for(const ch of letters)col=col*26+ch.charCodeAt(0)-64;const raw=nodes(c,'v')[0]?.textContent||'',type=c.getAttribute('t');out[col-1]=type==='s'?shared[+raw]||'':type==='inlineStr'?text(c):raw;}return out;});return {name:sh.getAttribute('name'),rows,date1904};});}
let importSheets=[],importPreview=[];
function importDialog(){modal('Import your study schedule',`<p>Upload a CSV or Excel workbook (.xlsx). Files are read locally.</p><label class="upload-zone">↑ Choose your schedule<input type="file" accept=".csv,.xlsx" onchange="loadSchedule(this.files[0])"></label><p class="screen-note">Recognized columns: Date, System, Plan & Targets (or Main Task), Hours, UWorld, Status, First Aid Target, B&B Target, Anki Target, New Card Budget, Secondary Task, Notes. Dates: YYYY-MM-DD or DD/MM/YYYY. Existing dates are updated only for supplied columns.</p><div id="import-result" aria-live="polite"></div>`)}
async function loadSchedule(file){if(!file)return;try{if(file.size>10e6)throw Error('Use a file smaller than 10 MB.');$('#import-result').textContent='Reading schedule…';if(/\.csv$/i.test(file.name))importSheets=[{name:'CSV',rows:parseCSV(await file.text())}];else if(/\.xlsx$/i.test(file.name))importSheets=await readXlsx(await file.arrayBuffer());else throw Error('Choose a .csv or .xlsx file.');if(!importSheets.length)throw Error('No worksheets found.');showImportSheet(0);}catch(err){$('#import-result').textContent=err.message;}}
function importDate(value,date1904=false){let s=String(value??'').trim();if(/^\d+(\.\d+)?$/.test(s)){const d=new Date(Date.UTC(date1904?1904:1899,date1904?0:11,date1904?1:30)+Math.floor(+s)*864e5);s=d.toISOString().slice(0,10);}else if(/^\d{1,2}[\/-]\d{1,2}[\/-]\d{4}$/.test(s)){const [d,m,y]=s.split(/[\/-]/);s=`${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;}return s;}
const importAliases={'date':'date:Date:start','studydate':'date:Date:start','datestart':'date:Date:start','datedatestart':'date:Date:start','system':'Primary System/Subject','primarysystemsubject':'Primary System/Subject','plantargets':'Main Task','plan':'Main Task','lesson':'Main Task','topic':'Main Task','maintask':'Main Task','hours':'Planned Hours','plannedhours':'Planned Hours','uworld':'UWorld Target','uworldtarget':'UWorld Target','uworldquestions':'UWorld Target','status':'Status','firstaidtarget':'First Aid Target','bbtarget':'B&B Target','ankitarget':'Anki Target','newcardbudget':'New Card Budget','secondarytask':'Secondary Task','notes':'Notes','daytype':'Day Type'};
function mapImport(rows,date1904){const nonempty=rows.filter(r=>r.some(x=>String(x??'').trim()));if(!nonempty.length)throw Error('This sheet is empty.');const headers=nonempty[0].map(h=>importAliases[String(h).toLowerCase().replace(/[^a-z]/g,'')]);if(!headers.includes('date:Date:start'))throw Error('A Date column is required in the first row.');const seen=new Set(),result=[],errors=[];nonempty.slice(1).forEach((row,i)=>{const f={};headers.forEach((key,j)=>{if(key&&row[j]!==undefined&&String(row[j]).trim()!=='')f[key]=String(row[j]).trim()});if(!Object.keys(f).length)return;f['date:Date:start']=importDate(f['date:Date:start'],date1904);let err=validPlan(f);if(!err&&seen.has(f['date:Date:start']))err='Duplicate date in this sheet.';if(err)errors.push(`Row ${i+2}: ${err}`);else{seen.add(f['date:Date:start']);result.push(f)}});if(errors.length)throw Error(errors.slice(0,8).join(' '));if(!result.length)throw Error('No valid schedule rows found.');if(result.length>1500)throw Error('Import up to 1,500 days at a time.');return result.sort((a,b)=>a['date:Date:start'].localeCompare(b['date:Date:start']));}
function showImportSheet(i){const selector=importSheets.length>1?`<label>Worksheet<select onchange="showImportSheet(+this.value)">${importSheets.map((s,j)=>`<option value="${j}" ${i===j?'selected':''}>${E(s.name)}</option>`).join('')}</select></label>`:'';try{importPreview=mapImport(importSheets[i].rows,importSheets[i].date1904);const updates=importPreview.filter(f=>D.daily.some(r=>dt(r)===f['date:Date:start'])).length;$('#import-result').innerHTML=selector+`<p>${importPreview.length-updates} new days · ${updates} existing days to update. Blank cells preserve existing values.</p>`+table(['Date','System','Plan','Hours'],importPreview.slice(0,8).map(f=>`<tr><td>${E(f['date:Date:start'])}</td><td>${E(f['Primary System/Subject'])}</td><td>${E(f['Main Task'])}</td><td>${E(f['Planned Hours'])}</td></tr>`))+`<p class="screen-note">Showing the first ${Math.min(8,importPreview.length)} rows. Break dates remain protected.</p><div class="modal-actions">${btn('Cancel','closeModal()')}${btn('Import '+importPreview.length+' days','commitImport()','primary')}</div>`;}catch(err){importPreview=[];$('#import-result').innerHTML=selector+`<p role="alert">${E(err.message)}</p>`;}}
function commitImport(){if(!importPreview.length)return;importPreview.forEach(upsertPlan);applyPause();persist();closeModal();render();toast('Schedule imported in date order. Calendar updated.');importPreview=[];}
